'use strict';
const $=id=>document.getElementById(id),video=$('video');
let data,trial,index=0,yaw=-0.48,pitch=0.36,drag=null;
const finite=x=>typeof x==='number'&&Number.isFinite(x),mm=(x,digits=2)=>finite(x)?`${x.toFixed(digits)} mm`:'unavailable';
function surface(id){const canvas=$(id),r=canvas.getBoundingClientRect(),d=devicePixelRatio||1;canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d);const ctx=canvas.getContext('2d');ctx.scale(d,d);return [ctx,r.width,r.height];}
function selectTrial(){video.pause();trial=data.trials[+$('trial').value];index=0;$('timeline').max=trial.frames.length-1;const m=trial.metrics;$('tau').textContent=`${(data.parameters.recovery_time_s*1000).toFixed(1)} ms`;$('rmse').textContent=mm(m.marker_rmse_mm,3);$('baseline').textContent=mm(m.instantaneous_baseline_marker_rmse_mm,3);$('coverage').textContent=`${(100*m.marker_frame_coverage).toFixed(0)}%`;$('recovery').textContent=`Recovery-only: model ${mm(m.recovery_marker_rmse_mm)}; instant baseline ${mm(m.instantaneous_baseline_recovery_rmse_mm)} over ${m.recovery_frames} frames.`;const n=trial.estimated.filter(Boolean).length;$('repair').textContent=n?`${n} book-input frames reconstructed under a maximum ${data.provenance.max_book_gap}-frame gap policy. Amber phase labels identify those frames.`:'No reconstructed book-input frames in this interval.';$('identification').textContent=data.parameters.weak_time_constant_identification?'Recovery time is weakly identified: substantially different τ values give similar training errors. This is a predictive approximation, not a precise material measurement.':'Recovery time is an effective parameter under the stated model assumptions.';refreshMarkerChoices();seek(0);}
function seek(i){index=Math.max(0,Math.min(trial.frames.length-1,Math.round(i)));video.currentTime=trial.frames[index]/data.video.fps;render();}
function overlay(){const [ctx,w,h]=surface('overlay'),sx=w/data.video.width,sy=h/data.video.height;ctx.lineWidth=1.3;for(const [name,color,cross] of [['observed','#b7ed93',false],['predicted','#ffb16c',true]]){if(!$(name).checked)continue;ctx.strokeStyle=color;trial[name][index].forEach(p=>{if(!p||!p.every(finite))return;const x=p[0]*sx,y=p[1]*sy;ctx.beginPath();if(cross){ctx.moveTo(x-4,y);ctx.lineTo(x+4,y);ctx.moveTo(x,y-4);ctx.lineTo(x,y+4);}else ctx.arc(x,y,3.5,0,Math.PI*2);ctx.stroke();});}}
function solid(){const [ctx,w,h]=surface('solid'),[L,W,H]=data.parameters.dimensions_mm,height=trial.heights[index],scale=Math.min(w/(L+W)*1.65,h/140);const project=([x,y,z])=>{x-=L/2;y-=W/2;const u=x*Math.cos(yaw)-y*Math.sin(yaw),v=x*Math.sin(yaw)+y*Math.cos(yaw);return [w/2+u*scale,h*.64+(v*Math.sin(pitch)-z*Math.cos(pitch))*scale,v*Math.cos(pitch)+z*Math.sin(pitch)];};function face(points,fill,stroke='#d5edb0'){const p=points.map(project);ctx.beginPath();p.forEach((a,i)=>i?ctx.lineTo(a[0],a[1]):ctx.moveTo(a[0],a[1]));ctx.closePath();ctx.fillStyle=fill;ctx.fill();ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke();}face([[-L*.2,-W*.4,-1],[L*1.2,-W*.4,-1],[L*1.2,W*1.4,-1],[-L*.2,W*1.4,-1]],'#202c25','#36453a');const v=[];for(const z of [0,height])for(const y of [0,W])for(const x of [0,L])v.push([x,y,z]);const faces=[[[0,1,5,4],'#829b64'],[[1,3,7,5],'#a4bd7a'],[[2,3,7,6],'#78945d'],[[0,2,6,4],'#99b86c'],[[4,5,7,6],'#cfdfa0']];faces.sort((a,b)=>a[0].reduce((s,i)=>s+project(v[i])[2],0)-b[0].reduce((s,i)=>s+project(v[i])[2],0));faces.forEach(([ids,color])=>face(ids.map(i=>v[i]),color));const book=trial.book[index];if(finite(book)&&book<H*1.8)face([[0,0,book],[L,0,book],[L,W,book],[0,W,book]],'#b1755b77','#ffb16c');ctx.fillStyle='#a7b5a9';ctx.font='11px monospace';ctx.fillText('DIMENSIONED PROXY · UNIFORM STRAIN',18,25);ctx.fillText('Drag to rotate · double-click to reset',18,h-17);}
function plot(){const [ctx,w,h]=surface('plot'),pad={l:35,r:12,t:15,b:25},pw=w-pad.l-pad.r,ph=h-pad.t-pad.b,values=[...trial.rmse,...trial.baseline_rmse].filter(finite),max=Math.max(1,...values)*1.12;ctx.font='10px monospace';for(let j=0;j<=4;j++){const y=pad.t+ph*j/4;ctx.strokeStyle='#344038';ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(w-pad.r,y);ctx.stroke();ctx.fillStyle='#a7b5a9';ctx.fillText((max*(1-j/4)).toFixed(1),0,y+3);}for(const [key,color] of [['baseline_rmse','#7cbaca'],['rmse','#ffb16c']]){ctx.strokeStyle=color;ctx.lineWidth=1.5;ctx.beginPath();let connected=false;trial[key].forEach((v,i)=>{if(!finite(v)){connected=false;return;}const x=pad.l+pw*i/(trial.frames.length-1),y=pad.t+ph*(1-v/max);if(connected)ctx.lineTo(x,y);else ctx.moveTo(x,y);connected=true;});ctx.stroke();}const x=pad.l+pw*index/(trial.frames.length-1);ctx.strokeStyle='#edf1e8';ctx.beginPath();ctx.moveTo(x,pad.t);ctx.lineTo(x,pad.t+ph);ctx.stroke();ctx.fillStyle='#a7b5a9';ctx.fillText('0 s',pad.l,h-4);ctx.fillText(((trial.frames.at(-1)-trial.frames[0])/data.parameters.capture_fps).toFixed(2)+' s',w-60,h-4);}
function render(){if(!trial)return;overlay();solid();plot();motionPlot();$('timeline').value=index;$('clock').textContent=`${((trial.frames[index]-trial.frames[0])/data.parameters.capture_fps).toFixed(3)} s · f ${trial.frames[index]}`;$('phase').textContent=(trial.contact[index]?'Contact':'Free / at rest')+(trial.estimated[index]?' · estimated book input':'');$('phase').style.color=trial.estimated[index]?'#ffb16c':'#b7ed93';$('height').textContent=`Foam ${mm(trial.heights[index])}`;$('input').textContent=`Book ${finite(trial.book[index])?mm(trial.book[index]):'outside view / unconstrained'}`;}
$('play').onclick=()=>{if(!trial)return;if(video.paused){if(index>=trial.frames.length-1)seek(0);video.play().catch(e=>showError('Video playback failed: '+e.message));}else video.pause();};video.onplay=()=>$('play').textContent='Pause';video.onpause=()=>$('play').textContent='Play';$('restart').onclick=()=>{if(trial){video.pause();seek(0);}};$('timeline').oninput=e=>{if(trial){video.pause();seek(+e.target.value);}};$('trial').onchange=selectTrial;$('speed').onchange=()=>video.playbackRate=+$('speed').value;for(const id of ['observed','predicted'])$(id).onchange=render;
const canvas=$('solid');canvas.onpointerdown=e=>{drag=[e.clientX,e.clientY];canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(!drag||!trial)return;yaw+=(e.clientX-drag[0])*.008;pitch=Math.max(.12,Math.min(1.2,pitch+(e.clientY-drag[1])*.006));drag=[e.clientX,e.clientY];solid();};canvas.onpointerup=()=>drag=null;canvas.onpointercancel=()=>drag=null;canvas.ondblclick=()=>{yaw=-.48;pitch=.36;if(trial)solid();};window.addEventListener('resize',render);
function tick(){if(trial&&!video.paused){const next=Math.round(video.currentTime*data.video.fps)-trial.frames[0];index=Math.max(0,Math.min(trial.frames.length-1,next));if(next>=trial.frames.length-1){video.pause();seek(trial.frames.length-1);}else render();}requestAnimationFrame(tick);}function showError(message){$('error').hidden=false;$('error').textContent=message;}
fetch('results.json').then(r=>{if(!r.ok)throw Error('Export missing. Run python viewer.py export first.');return r.json();}).then(d=>{data=d;for(let i=0;i<d.trials.length;i++)$('trial').add(new Option(`Press ${d.trials[i].id}`,i));video.src=d.video.src;video.addEventListener('loadedmetadata',selectTrial,{once:true});video.addEventListener('seeked',render);video.addEventListener('error',()=>showError('Cannot load footage. Check video.mp4 and browser codec support.'));requestAnimationFrame(tick);}).catch(e=>showError(e.message));
